  "BioTech & Synthetic Biology": "bio", "XR, Metaverse & Spatial Computing": "xr", "SportsTech & Wellness": "heartHand",
  "AgriTech & Food Security": "heartHand", "PetTech & Animal Care": "pet", "Cybersecurity & Privacy": "shield",
  "SpaceTech & Downstream Data": "shield", "Clean Energy & Storage": "shield", "FashionTech & Sustainable Apparel": "shirt",
