// ---------- State ----------
const freshState = () => ({
  roles: [], // in pick order; drives the per-role screens
  services: {}, // role -> Set of business service ids
  skills: new Set(),
  artefacts: new Set(), // value construct ids
  priority: "",
  industries: new Set(),
  gigs: new Set(),
  nano: "", // "yes" | "no"
});
let state = freshState();

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
const el = (tag, cls, text) => {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
};
const icon = (file, cls = "") => {
  const img = el("img", cls);
  img.src = A + file;
  img.alt = "";
  return img;
};

// ---------- Steps ----------
// Route list grows with the number of roles picked: one "Which aspects of <role>" screen per role.
const steps = () => [
  "welcome", "about", "priority", "roles", ...state.roles.map((_, i) => `role-${i + 1}`),
  VARIANT, "industries", "gigs", "nano", "contact",
];
const roleIndex = (route) => (route.startsWith("role-") ? Number(route.slice(5)) - 1 : -1);
const stepKind = (route) => (roleIndex(route) >= 0 ? "services" : route);

const HEADERS = {
  about: { eyebrow: "About You", title: "Let’s get to know you better", desc: "Tell us about yourself" },
  priority: { eyebrow: "Your Goal", title: "What is your current career priority", desc: "Choose what you want to focus on right now" },
  roles: {
    eyebrow: "Role Interests",
    title: "Which of these roles would you like to be paid for",
    desc: "At this point, your level of experience with the roles is irrelevant. Just think about what you would like to be paid to do",
    count: () => `Select Up to ${MAX_ROLES} roles (${state.roles.length}/${MAX_ROLES} selected)`,
  },
  services: {
    desc: "Select all the ones that fascinate you. You can always modify this later",
  },
  skills: {
    eyebrow: "Mapping Your Strengths",
    title: "Which of these skills do you currently possess?",
    desc: "Ensure transparency here as you’ll be required to validate your skill set later. You can always modify this later",
    count: () => `(${visibleSkills().size} selected)`,
  },
  artefacts: {
    eyebrow: "Mapping Your Capabilities",
    title: "Which of these artefacts are you presently capable of producing?",
    desc: "It’s perfectly fine if none of these make sense yet. We’re here to help you learn",
    count: () => `(${visibleArtefacts().size} selected)`,
  },
  industries: {
    eyebrow: "Your Industry Affinity",
    title: "Where would you like to make an impact through your work?",
    desc: "Think of the causes or fields you would like to contribute towards improving",
    count: () => `(${state.industries.size} selected)`,
  },
  gigs: { eyebrow: "Brand Engagement", title: "Which of these engagement gigs would you be interested in?", desc: "Choose all where you’d like to participate" },
  nano: { eyebrow: "Nano Influencer", title: "Would you like to sign up as a nano influencer?", desc: "Promote partner brands around your campus" },
  contact: { eyebrow: "Contact Details", title: "How do we get in touch?", desc: "Please provide your contact details" },
};

function renderHeader(route) {
  const kind = stepKind(route);
  const h = HEADERS[kind];
  const title = $("[data-title]");
  if (kind === "services") {
    const role = state.roles[roleIndex(route)];
    $("[data-eyebrow]").textContent = `Let’s talk about ‘${role}’`;
    title.textContent = "Which Aspects Of ";
    title.append(el("em", "", `‘${role}’`), " Would You Prefer Working On?");
  } else {
    $("[data-eyebrow]").textContent = h.eyebrow;
    title.textContent = h.title;
  }
  $("[data-desc]").textContent = h.desc;
  updateCount(route);
}

function updateCount(route = currentRoute()) {
  const kind = stepKind(route);
  let text = HEADERS[kind]?.count?.() ?? "";
  if (kind === "services") text = `(${servicesFor(state.roles[roleIndex(route)]).size} selected)`;
  $("[data-count]").textContent = text;
}

// ---------- Routing ----------
const currentRoute = () => location.hash.slice(1) || "welcome";
const go = (route) => {
  if (location.hash.slice(1) === route) render();
  else location.hash = route;
};

function render() {
  let route = currentRoute();
  const done = route === "done";
  // Deep links and stale history entries fall back to the first step that still needs an answer.
  if (!done) {
    const list = steps();
    if (!list.includes(route)) route = list[0];
    const blocked = list.slice(0, list.indexOf(route)).find((s) => validate(s, true));
    if (blocked) route = blocked;
    if (route !== currentRoute()) return history.replaceState(null, "", "#" + route), render();
  }

  const welcome = route === "welcome";
  document.body.classList.toggle("is-done", done);
  document.body.classList.toggle("is-welcome", welcome);
  setError("");
  if (done || welcome) return window.scrollTo(0, 0);

  const kind = stepKind(route);
  $$(".pf-step").forEach((s) => s.classList.toggle("is-active", s.dataset.step === kind));
  if (kind === "services") renderServices(state.roles[roleIndex(route)]);
  if (kind === "skills") renderSkills();
  if (kind === "artefacts") renderArtefacts();
  renderHeader(route);

  // The welcome screen sits outside the progress bar.
  const list = steps();
  const i = list.indexOf(route);
  $("[data-progress]").style.width = `${(i / list.length) * 100}%`;
  $("[data-back]").disabled = i === 0;
  $("[data-next-label]").textContent = route === "contact" ? "Submit" : "Next";
  window.scrollTo(0, 0);
}
window.addEventListener("hashchange", render);

// ---------- Validation ----------
const setError = (msg) => ($("[data-step-error]").textContent = msg);
const fieldError = (form, name, msg) => {
  const f = $(`[data-field="${name}"]`, form);
  f.classList.toggle("has-error", !!msg);
  $(".pf-error", f).textContent = msg || "";
  return msg;
};

// Returns an error message for the step (or "" when it's complete). `quiet` skips marking fields.
function validate(route, quiet = false) {
  const kind = stepKind(route);
  const check = (form, name, msg) => (quiet ? msg : fieldError(form, name, msg));
  if (kind === "welcome") {
    const msg = chosenCollege() ? "" : otherOpen() ? "Type your college name to continue." : "Select your college to continue.";
    if (!quiet) {
      $("[data-welcome-error]").textContent = msg;
      $(otherOpen() ? '[data-field="collegeOther"]' : '[data-field="college"]').classList.toggle("has-error", !!msg);
    }
    return msg;
  }
  if (kind === "about") {
    const form = $('[data-step="about"]');
    const errs = [
      check(form, "name", form.elements.name.value.trim() ? "" : "Please enter your full name."),
      check(form, "study", form.study.value.trim() ? "" : "Please enter your field of study."),
    ];
    return errs.find(Boolean) ? "Fill in the highlighted fields to continue." : "";
  }
  if (kind === "priority") return state.priority ? "" : "Pick your current career priority to continue.";
  if (kind === "roles") return state.roles.length ? "" : "Pick at least one role to continue.";
  if (kind === "services") {
    const role = state.roles[roleIndex(route)];
    return servicesFor(role).size ? "" : `Pick at least one aspect of ${role} to continue.`;
  }
  if (kind === "industries") return state.industries.size ? "" : "Pick at least one industry to continue.";
  if (kind === "nano") {
    if (!state.nano) return "Choose Yes or No to continue.";
    if (state.nano === "no") return "";
    const form = $('[data-step="nano"]');
    const handle = form.instagram.value.trim().replace(/^@/, "");
    const errs = [
      check(form, "instagram", /^[\w.]{1,30}$/.test(handle) ? "" : "Enter your Instagram handle."),
      check(form, "followers", /^\d+$/.test(form.followers.value.trim()) ? "" : "Enter your follower count as a number."),
    ];
    return errs.find(Boolean) ? "Fill in the highlighted fields to continue." : "";
  }
  if (kind === "contact") {
    const form = $('[data-step="contact"]');
    const email = form.email.value.trim();
    const mobile = form.mobile.value.replace(/\D/g, "");
    const linkedin = form.linkedin.value.trim();
    const errs = [
      check(form, "email", /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? "" : "Enter a valid email address."),
      check(form, "mobile", mobile.length === 10 ? "" : "Enter a 10-digit mobile number."),
      check(form, "linkedin", !linkedin || /linkedin\.com\//i.test(linkedin) ? "" : "Enter your LinkedIn profile link."),
    ];
    return errs.find(Boolean) ? "Fill in the highlighted fields to continue." : "";
  }
  return "";
}

// ---------- Welcome ----------
const welcomeForm = $(".pf-welcome__start");
const collegeSelect = $("#pf-college");
const otherField = $('[data-field="collegeOther"]');
const otherOpen = () => !otherField.hidden;
const chosenCollege = () => (otherOpen() ? $("#pf-college-other").value.trim() : collegeSelect.value);
COLLEGES.forEach((c) => collegeSelect.add(new Option(c, c)));
const syncCollegeSelect = () => collegeSelect.classList.toggle("is-empty", !collegeSelect.value);
syncCollegeSelect();
const clearWelcomeError = () => {
  $("[data-welcome-error]").textContent = "";
  $$(".pf-welcome__select", welcomeForm).forEach((f) => f.classList.remove("has-error"));
};
collegeSelect.addEventListener("change", () => (syncCollegeSelect(), clearWelcomeError()));
$("#pf-college-other").addEventListener("input", clearWelcomeError);
// "Start a pod" swaps the list for a free-text college name.
$("[data-start-pod]").addEventListener("click", () => {
  collegeSelect.closest(".pf-welcome__select").hidden = true;
  otherField.hidden = false;
  clearWelcomeError();
  $("#pf-college-other").focus();
});
welcomeForm.addEventListener("submit", (e) => (e.preventDefault(), next()));

function resetWelcome() {
  welcomeForm.reset();
  collegeSelect.closest(".pf-welcome__select").hidden = false;
  otherField.hidden = true;
  syncCollegeSelect();
  clearWelcomeError();
}

// Value proposition carousel: auto-advances, pauses on hover/focus and for reduced motion.
const propDots = $("[data-prop-dots]");
let prop = 0;
function showProp(i) {
  prop = (i + VALUE_PROPS.length) % VALUE_PROPS.length;
  $("[data-prop-title]").textContent = VALUE_PROPS[prop][0];
  $("[data-prop-body]").textContent = VALUE_PROPS[prop][1];
  $$("button", propDots).forEach((b, n) => b.setAttribute("aria-current", String(n === prop)));
}
VALUE_PROPS.forEach((p, n) => {
  const b = el("button");
  b.type = "button";
  b.setAttribute("aria-label", `Show ${p[0]}`);
  b.append(icon("dot.svg", "is-idle"), icon("dot-active.svg", "is-current"));
  b.addEventListener("click", () => showProp(n));
  propDots.append(b);
});
showProp(0);
const props = $(".pf-props");
let paused = matchMedia("(prefers-reduced-motion: reduce)").matches;
props.addEventListener("mouseenter", () => (paused = true));
props.addEventListener("mouseleave", () => (paused = matchMedia("(prefers-reduced-motion: reduce)").matches));
setInterval(() => !paused && document.body.classList.contains("is-welcome") && showProp(prop + 1), 5000);

// ---------- About You ----------
const yearSelect = $('[name="year"]');
for (let y = 2020; y <= 2032; y++) yearSelect.add(new Option(y, y, false, y === 2026));
$$(".pf-fields input").forEach((input) =>
  input.addEventListener("input", () => {
    const f = input.closest(".pf-field"); // radios sit outside a .pf-field
    if (f?.classList.contains("has-error")) {
      f.classList.remove("has-error");
      $(".pf-error", f).textContent = "";
    }
  })
);
$$(".pf-fields").forEach((form) => form.addEventListener("submit", (e) => (e.preventDefault(), next())));
// Mobile number groups as "00000 00000", matching the placeholder.
$('[name="mobile"]').addEventListener("input", (e) => {
  const d = e.target.value.replace(/\D/g, "").slice(0, 10);
  e.target.value = d.length > 5 ? `${d.slice(0, 5)} ${d.slice(5)}` : d;
});

// ---------- Collapsible group (Niche Container) ----------
function group(title, cls = "pf-group") {
  const section = el("section", cls);
  const head = el("button", "pf-group__head");
  head.type = "button";
  head.setAttribute("aria-expanded", "true");
  head.append(el("span", "", title), icon("expand-less.svg"));
  head.addEventListener("click", () => {
    const collapsed = section.classList.toggle("is-collapsed");
    head.setAttribute("aria-expanded", String(!collapsed));
  });
  const body = el("div", "pf-group__body");
  section.append(head, body);
  return { section, body };
}

// ---------- Option cards (career priority, engagement gigs) ----------
// Same states as the Role Option: plus icon, darker plus on hover, red tick once picked.
function optionList(container, options, isOn, onPick) {
  const cards = options.map(([title, desc]) => {
    const btn = el("button", "pf-option");
    btn.type = "button";
    const text = el("span", "pf-option__text");
    text.append(el("span", "pf-option__title", title), el("span", "pf-option__desc", desc));
    btn.append(text, icon("add.svg", "pf-icon pf-icon--add"), icon("add-hover.svg", "pf-icon pf-icon--hover"), icon("done.svg", "pf-icon pf-icon--done"));
    btn.addEventListener("click", () => (onPick(title), sync(), setError("")));
    container.append(btn);
    return [btn, title];
  });
  const sync = () =>
    cards.forEach(([btn, title]) => {
      btn.classList.toggle("is-selected", isOn(title));
      btn.setAttribute("aria-pressed", String(isOn(title)));
    });
  return sync;
}
const syncPriority = optionList($("#pf-priority"), PRIORITIES, (t) => state.priority === t, (t) => (state.priority = t));
const syncGigs = optionList($("#pf-gigs"), GIGS, (t) => state.gigs.has(t), (t) => (state.gigs.has(t) ? state.gigs.delete(t) : state.gigs.add(t)));

// ---------- Nano influencer ----------
const nanoForm = $('[data-step="nano"]');
const nanoFields = $(".pf-nano__fields", nanoForm);
function syncNano() {
  $$(".pf-radio", nanoForm).forEach((r) => r.classList.toggle("is-checked", $("input", r).checked));
  nanoFields.hidden = state.nano !== "yes"; // Figma: only shown when "Yes" is picked
}
$$('[name="nano"]', nanoForm).forEach((input) =>
  input.addEventListener("change", () => ((state.nano = input.value), syncNano(), setError("")))
);
// Followers accepts digits only.
nanoForm.followers.addEventListener("input", (e) => (e.target.value = e.target.value.replace(/\D/g, "").slice(0, 9)));
syncNano();

// ---------- Roles ----------
const rolesEl = $("#pf-roles");
DATA.domains.forEach((domain) => {
  const { section, body } = group(domain.name);
  domain.roles.forEach((role) => {
    const btn = el("button", "pf-role");
    btn.type = "button";
    btn.dataset.role = role;
    btn.setAttribute("aria-pressed", "false");
    btn.append(el("span", "", role), icon("add.svg", "pf-icon pf-icon--add"), icon("add-hover.svg", "pf-icon pf-icon--hover"), icon("done.svg", "pf-icon pf-icon--done"));
    btn.addEventListener("click", () => toggleRole(role));
    body.append(btn);
  });
  rolesEl.append(section);
});

function toggleRole(role) {
  const i = state.roles.indexOf(role);
  if (i >= 0) {
    state.roles.splice(i, 1);
    delete state.services[role];
  } else if (state.roles.length >= MAX_ROLES) {
    return setError(`You can pick up to ${MAX_ROLES} roles. Remove one to choose another.`);
  } else {
    state.roles.push(role);
  }
  setError("");
  syncRoles();
}

function syncRoles() {
  const full = state.roles.length >= MAX_ROLES;
  $$(".pf-role", rolesEl).forEach((b) => {
    const on = state.roles.includes(b.dataset.role);
    b.classList.toggle("is-selected", on);
    b.classList.toggle("is-capped", full && !on);
    b.setAttribute("aria-pressed", String(on));
  });
  updateCount();
}

// ---------- Business services per role ----------
const servicesFor = (role) => (state.services[role] ||= new Set());
const servicesEl = $("#pf-services");

function renderServices(role) {
  servicesEl.replaceChildren();
  const picked = servicesFor(role);
  // Group by category; categories and cards follow the role's relevance ranking.
  const byCategory = new Map();
  DATA.roleServices[role].forEach(([id]) => {
    const s = DATA.services[id];
    if (!byCategory.has(s.category)) byCategory.set(s.category, []);
    byCategory.get(s.category).push(id);
  });
  byCategory.forEach((ids, category) => {
    const { section, body } = group(category);
    ids.forEach((id) => body.append(serviceCard(id, picked)));
    servicesEl.append(section);
  });
}

function serviceCard(id, picked) {
  const s = DATA.services[id];
  const card = el("div", "pf-service");
  card.tabIndex = 0;
  card.setAttribute("role", "button");
  const sync = () => {
    card.classList.toggle("is-selected", picked.has(id));
    card.setAttribute("aria-pressed", String(picked.has(id)));
  };
  const toggle = () => {
    picked.has(id) ? picked.delete(id) : picked.add(id);
    sync();
    setError("");
    updateCount();
  };
  card.addEventListener("click", (e) => !e.target.closest(".pf-learn") && toggle());
  card.addEventListener("keydown", (e) => {
    if (e.target === card && (e.key === "Enter" || e.key === " ")) e.preventDefault(), toggle();
  });

  const top = el("div", "pf-service__top");
  const heart = el("span", "pf-service__heart");
  heart.append(icon("heart-border.svg", "is-default"), icon("heart-border-hover.svg", "is-hover"), icon("heart.svg", "is-on"));
  top.append(el("p", "pf-service__title", s.title), heart);

  const deliverable = el("div", "pf-service__deliverable");
  const row = el("div", "pf-deliverable");
  const dIcon = el("span", "pf-deliverable__icon");
  dIcon.append(icon("deliverable.svg"));
  const learn = el("span", "pf-learn", "?");
  learn.tabIndex = 0;
  learn.setAttribute("aria-label", `About ${s.deliverable}`);
  const tip = el("span", "pf-tip");
  tip.append(el("b", "", s.deliverable), s.deliverableDesc);
  learn.append(tip);
  row.append(dIcon, el("p", "pf-deliverable__name", s.deliverable), learn);
  deliverable.append(el("p", "pf-service__label", "Deliverable:"), row);

  card.append(top, el("p", "pf-service__desc", s.desc), deliverable);
  sync();
  return card;
}

// ---------- Skills ----------
// Technical skills from the value constructs behind the services picked for each role.
function skillsForRole(role) {
  const score = new Map();
  servicesFor(role).forEach((id) =>
    (DATA.skills[id] || []).forEach(([skill, w]) => score.set(skill, (score.get(skill) || 0) + w))
  );
  return [...score].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, SKILLS_PER_ROLE).map(([s]) => s);
}
// Only skills still on screen count (a skill picked earlier may drop off if services change).
function visibleSkills() {
  const shown = new Set(state.roles.flatMap(skillsForRole));
  return new Set([...state.skills].filter((s) => shown.has(s)));
}

const skillsEl = $("#pf-skills");
function renderSkills() {
  skillsEl.replaceChildren();
  state.roles.forEach((role) => {
    const { section, body } = group(role, "pf-skill-group");
    const list = skillsForRole(role);
    if (!list.length) body.append(el("p", "pf-empty", "No skills are mapped to these services yet."));
    list.forEach((skill) => {
      const chip = el("button", "pf-skill", skill);
      chip.type = "button";
      chip.dataset.skill = skill;
      chip.addEventListener("click", () => {
        state.skills.has(skill) ? state.skills.delete(skill) : state.skills.add(skill);
        syncSkills();
      });
      body.append(chip);
    });
    skillsEl.append(section);
  });
  syncSkills();
}
// A skill shared by two roles toggles in both places.
function syncSkills() {
  $$(".pf-skill", skillsEl).forEach((c) => {
    const on = state.skills.has(c.dataset.skill);
    c.classList.toggle("is-selected", on);
    c.setAttribute("aria-pressed", String(on));
  });
  updateCount();
}

// ---------- Value construct artefacts ----------
// Artefacts of the value constructs mapped to the services picked for each role, most relevant first.
function artefactsForRole(role) {
  const score = new Map();
  servicesFor(role).forEach((id) =>
    (DATA.serviceVcs[id] || []).forEach(([vc, w]) => score.set(vc, (score.get(vc) || 0) + w))
  );
  return [...score].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, ARTEFACTS_PER_ROLE).map(([vc]) => vc);
}
function visibleArtefacts() {
  const shown = new Set(state.roles.flatMap(artefactsForRole));
  return new Set([...state.artefacts].filter((vc) => shown.has(vc)));
}

const artefactsEl = $("#pf-artefacts");
function renderArtefacts() {
  artefactsEl.replaceChildren();
  state.roles.forEach((role) => {
    const { section, body } = group(role);
    const list = artefactsForRole(role);
    if (!list.length) body.append(el("p", "pf-empty", "No artefacts are mapped to these services yet."));
    list.forEach((vc) => {
      const v = DATA.vcs[vc];
      const card = el("button", "pf-artefact");
      card.type = "button";
      card.dataset.vc = vc;
      const text = el("span", "pf-artefact__text");
      text.append(el("span", "pf-artefact__title", v.artefact), el("span", "pf-artefact__desc", v.artefactDesc));
      card.append(text, el("span", "pf-artefact__source", `Source: ${v.name}`));
      card.addEventListener("click", () => {
        state.artefacts.has(vc) ? state.artefacts.delete(vc) : state.artefacts.add(vc);
        syncArtefacts();
      });
      body.append(card);
    });
    artefactsEl.append(section);
  });
  syncArtefacts();
}
// An artefact shared by two roles toggles in both places.
function syncArtefacts() {
  $$(".pf-artefact", artefactsEl).forEach((c) => {
    const on = state.artefacts.has(c.dataset.vc);
    c.classList.toggle("is-selected", on);
    c.setAttribute("aria-pressed", String(on));
  });
  updateCount();
}

// ---------- Industries ----------
// Icons are inlined so CSS can switch their fill per state (default / hover / selected).
const svgCache = {};
const loadSvg = (file) => (svgCache[file] ||= fetch(I + file).then((r) => r.text()));
let svgInstance = 0;
function inlineSvg(layer, file) {
  loadSvg(file).then((markup) => {
    const p = `pf${svgInstance++}-`; // namespace ids so clip paths don't collide between icons
    layer.innerHTML = markup.replace(/id="([^"]+)"/g, `id="${p}$1"`).replace(/url\(#([^)]+)\)/g, `url(#${p}$1)`);
  });
}

const industriesEl = $("#pf-industries");
DATA.industries.forEach(({ name, subs }) => {
  const card = el("button", "pf-industry");
  card.type = "button";
  card.setAttribute("aria-pressed", "false");
  const ic = el("span", "pf-industry__icon");
  ic.setAttribute("aria-hidden", "true");
  (ICONS[INDUSTRY_ICON[name]] || ICONS.brain).forEach(({ file, inset }) => {
    const layer = el("span");
    layer.style.inset = inset;
    inlineSvg(layer, file);
    ic.append(layer);
  });
  const subsEl = el("span", "pf-industry__subs");
  subs.forEach((s) => subsEl.append(el("span", "", s)));
  card.append(ic, el("span", "pf-industry__name", name), subsEl);
  card.addEventListener("click", () => {
    const on = !state.industries.has(name);
    on ? state.industries.add(name) : state.industries.delete(name);
    card.classList.toggle("is-selected", on);
    card.setAttribute("aria-pressed", String(on));
    setError("");
    updateCount();
  });
  industriesEl.append(card);
});

// ---------- Navigation ----------
function next() {
  const route = currentRoute();
  const err = validate(route);
  if (err) return setError(err);
  const list = steps();
  if (route === "contact") return submit();
  go(list[list.indexOf(route) + 1]);
}
$("[data-next]").addEventListener("click", next);
$("[data-back]").addEventListener("click", () => {
  const list = steps();
  go(list[Math.max(0, list.indexOf(currentRoute()) - 1)]);
});

// ---------- Submit + retake ----------
function submit() {
  const about = $('[data-step="about"]');
  const contact = $('[data-step="contact"]');
  const shownSkills = visibleSkills();
  const shownArtefacts = visibleArtefacts();
  const payload = {
    variant: VARIANT,
    college: chosenCollege(),
    about: { name: about.elements.name.value.trim(), fieldOfStudy: about.study.value.trim(), graduationYear: Number(about.year.value) },
    careerPriority: state.priority,
    roles: state.roles.map((role) => ({
      role,
      businessServices: [...servicesFor(role)].map((id) => ({ id, title: DATA.services[id].title })),
      ...(VARIANT === "skills"
        ? { skills: skillsForRole(role).filter((s) => shownSkills.has(s)) }
        : {
            artefacts: artefactsForRole(role)
              .filter((vc) => shownArtefacts.has(vc))
              .map((vc) => ({ vcId: vc, artefact: DATA.vcs[vc].artefact, valueConstruct: DATA.vcs[vc].name })),
          }),
    })),
    industries: [...state.industries],
    engagementGigs: [...state.gigs],
    nanoInfluencer:
      state.nano === "yes"
        ? { signUp: true, instagram: "@" + nanoForm.instagram.value.trim().replace(/^@/, ""), followers: Number(nanoForm.followers.value) }
        : { signUp: false },
    contact: {
      email: contact.email.value.trim(),
      mobile: "+91 " + contact.mobile.value.replace(/\D/g, ""),
      linkedin: contact.linkedin.value.trim(),
    },
    submittedAt: new Date().toISOString(),
  };
  console.log("Caarya profiling submission", payload);
  try {
    localStorage.setItem("caarya-profiling-last", JSON.stringify(payload));
  } catch {}
  go("done");
}

$("[data-retake]").addEventListener("click", () => {
  state = freshState();
  $$(".pf-fields").forEach((f) => f.reset());
  $$(".pf-field.has-error").forEach((f) => f.classList.remove("has-error"));
  $$(".pf-industry").forEach((c) => (c.classList.remove("is-selected"), c.setAttribute("aria-pressed", "false")));
  servicesEl.replaceChildren();
  skillsEl.replaceChildren();
  artefactsEl.replaceChildren();
  resetWelcome();
  syncRoles();
  syncPriority();
  syncGigs();
  syncNano();
  go("welcome");
});

// ---------- Back to top ----------
const toTop = $(".pf-to-top");
window.addEventListener("scroll", () => toTop.classList.toggle("is-visible", window.scrollY > 400), { passive: true });
toTop.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));

render();
